"""A tiny tile API for lab 38. Do not edit this file.

It models the four operations every tile language has, on the CPU, in plain
torch. The names follow Triton (`tl.arange`, `tl.load`, `tl.store`, `tl.dot`),
and the behavior is the part that matters here:

- A tile is a 2-D torch tensor. You address it with a vector of row indices
  and a vector of column indices.
- `load_tile` and `store_tile` raise `OutOfBounds` when an index that is not
  masked off falls outside the array. A real kernel reads whatever bytes lie
  there, or faults, so the fixture turns that silent bug into an exception.
- A masked-off element of a load takes the value `other`. A masked-off element
  of a store writes nothing.
- `BlockSpec` is the Pallas pairing of a block shape and an index map.
- `mma` accumulates in float32, like a tensor core with a float32 accumulator.

`STATS` counts the calls, so a test can check how many tiles a program moves.
"""

from __future__ import annotations

from typing import Callable, NamedTuple

STATS = {"loads": 0, "stores": 0, "mmas": 0}


class BlockSpec(NamedTuple):
    """Which block of an array one grid point sees, as in Pallas.

    `index_map` takes the grid indices and returns one *block index* per array
    dimension. Block index 2 of a block of 8 starts at element 16.
    """

    block_shape: tuple
    index_map: Callable


class OutOfBounds(IndexError):
    """A load or a store touched an element outside the array."""


def reset_stats() -> None:
    for key in STATS:
        STATS[key] = 0


def arange(n: int):
    """Indices 0, 1, ..., n - 1, like `tl.arange(0, n)`."""
    import torch

    return torch.arange(n)


def _grid(rows, cols, mask, shape):
    import torch

    r = rows[:, None].expand(len(rows), len(cols))
    c = cols[None, :].expand(len(rows), len(cols))
    inside = (r >= 0) & (r < shape[0]) & (c >= 0) & (c < shape[1])
    if mask is None:
        live = torch.ones_like(inside)
    else:
        live = torch.broadcast_to(mask.to(torch.bool), inside.shape)
    bad = live & ~inside
    if bad.any():
        i, j = (int(v) for v in bad.nonzero()[0])
        raise OutOfBounds(
            f"element ({int(r[i, j])}, {int(c[i, j])}) is outside an array of shape "
            f"{tuple(shape)} and the mask does not turn it off"
        )
    return r, c, live


def load_tile(x, rows, cols, mask=None, other=0.0):
    """Load `x[rows[:, None], cols[None, :]]` as a (len(rows), len(cols)) tile.

    `mask` is a bool tensor that broadcasts to the tile. Elements where it is
    False are not read and take the value `other`.
    """
    import torch

    r, c, live = _grid(rows, cols, mask, x.shape)
    out = torch.full(live.shape, float(other), dtype=x.dtype)
    out[live] = x[r[live], c[live]]
    STATS["loads"] += 1
    return out


def store_tile(y, rows, cols, tile, mask=None):
    """Store `tile` at `y[rows[:, None], cols[None, :]]`, where `mask` is True."""
    r, c, live = _grid(rows, cols, mask, y.shape)
    y[r[live], c[live]] = tile[live].to(y.dtype)
    STATS["stores"] += 1


def mma(a, b, acc):
    """Return `acc + a @ b`, with a float32 accumulator."""
    STATS["mmas"] += 1
    return acc.float() + a.float() @ b.float()
